#[allow(unused_variables)] fn ability_0_affects(q: &dyn LayerQuery, source: ObjectId, affected: ObjectId, so_far: &Chars) -> bool { let asker = &Asker::new(source, q.controller(source)); ((*so_far).is(CardType::Creature) && Some(asker.controller) == Some(q.controller(affected)) && (i64::from(q.state().obj(affected).counters(CounterKind::PlusOne))) > (0i64)) }
#[allow(unused_variables)] fn ability_0_0_rule(q: &dyn Query, source: ObjectId, blocker: ObjectId, attacker: ObjectId) -> bool { let asker = &Asker::new(source, q.controller(source)); !((q.chars(attacker).is(CardType::Creature) && Some(asker.controller) == Some(q.controller(attacker)) && (i64::from(q.state().obj(attacker).counters(CounterKind::PlusOne))) > (0i64)) && true) }

